parameters.jsCode:
// Extract and normalize log lines from various shipper formats
const body = $input.first().json.body;
const MAX_LINES = 50;

let logLines = [];

// Handle array of log objects (Filebeat/Fluentd format)
if (Array.isArray(body)) {
  logLines = body.map(entry => {
    const msg = entry.message || entry.log || entry['@message'] || JSON.stringify(entry);
    const ts = entry['@timestamp'] || entry.timestamp || '';
    const level = entry.level || entry.severity || '';
    return `[${ts}] [${level}] ${msg}`.trim();
  });
} else if (body?.logs) {
  // Handle {logs: [...]} format
  logLines = Array.isArray(body.logs) ? body.logs : [body.logs];
} else if (typeof body === 'string') {
  // Handle raw text log dump
  logLines = body.split('\n').filter(l => l.trim());
} else {
  logLines = [JSON.stringify(body)];
}

// Trim to MAX_LINES most recent
const trimmed = logLines.slice(-MAX_LINES);
const source = body?.source || body?.[0]?.host?.name || 'unknown-source';

return [{
  json: {
    log_text: trimmed.join('\n'),
    log_count: trimmed.length,
    source: source,
    timestamp: new Date().toISOString()
  }
}];

const rawText = $input.first().json.content[0].text;
let analysis;
try {
  analysis = JSON.parse(rawText);
} catch (e) {
  analysis = { anomalies: [], errors: [], security: [], performance: [], health_score: 50, summary: rawText };
}

const hasIssues = analysis.anomalies.length > 0 || analysis.errors.length > 0 || analysis.security.length > 0;
const healthEmoji = analysis.health_score >= 80 ? '🟢' : analysis.health_score >= 50 ? '🟡' : '🔴';

return [{
  json: {
    ...analysis,
    has_issues: hasIssues,
    health_emoji: healthEmoji,
    source: $('Normalize Log Lines').first().json.source,
    log_count: $('Normalize Log Lines').first().json.log_count,
    timestamp: $('Normalize Log Lines').first().json.timestamp
  }
}];

